    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "at(3,1)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "recover_cart_after_item",
    "text": "After interacting at the item location (3,1), the shopper is obliged to recover a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "retrieve_at_cart_bay",
    "text": "Whenever the shopper is at the cart bay at (3,3) without a cart, they are obliged to interact there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
