          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "cart_required_exit_corridor",
    "text": "The shopper is prohibited from moving along the exit corridor from (2,7) through (11,7) without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "or": [
              "at(2,7)",
              "at(3,7)",
              "at(4,7)",
              "at(5,7)",
              "at(6,7)",
              "at(7,7)",
              "at(8,7)",
              "at(9,7)",
              "at(10,7)",
              "at(11,7)"
            ]
          }
        ]
      }
    }
